import type {EndpointDirectoryV3, EnvNameV3} from '@smart/endpoint-directory';
import type {ClientConfig} from '@smart/feature-app/react';
import {FeatureApp, createFeatureAppIntegrator} from '@smart/feature-app/react';
import {getLanguageTag} from '@smart/locale-service';
import {ComponentProvider} from '@smart/react-components';
import type {MarketId} from '@smart/types';
import {fetchFeatureFlags, setGlobalFeatureFlags} from '@smart/utils';
import * as React from 'react';
import {FEATURE_FLAGS} from '../../types/common.types';
import './integrator.scss';

setGlobalFeatureFlags({
  ENABLE_FALLBACK_PAYMENT: {
    enabledGlobally: false,
    markets: {
      DE: true,
      BE: true,
      FR: true,
      SE: true,
      GB: true,
      ES: true,
      CH: true,
    },
  },
  ENABLE_SHOWROOM_CART_APPROVAL_FLOW: {
    enabledGlobally: false,
  },

  ENABLE_NEW_PRICE_STRUCTURE_CASH_BUY: {
    enabledGlobally: true,
  },
  ENABLE_TOTAL_ENTRY_PRICE_WITH_DISCOUNT: {
    enabledGlobally: false,
    markets: {
      AT: true,
    },
  },
  ENABLE_MIGRATED_STEPPER: {
    enabledGlobally: false,
    markets: {
      FR: true,
      PT: true,
      DE: true,
    },
  },
  [FEATURE_FLAGS.ENABLE_EDITABLE_VAT_FIELDS]: {
    enabledGlobally: false,
    markets: {
      DE: true,
      GB: true,
    },
  },
  [FEATURE_FLAGS.ENABLE_NEW_PREFERRED_DELIVERY_DATE_FORMAT]: {
    enabledGlobally: true,
  },
  ENABLE_NOT_AUTH_FLOW: {
    enabledGlobally: false,
    markets: {
      DE: true,
      GB: true,
      ES: true,
    },
  },

  ENABLE_MODEL_YEAR: {
    enabledGlobally: false,
    markets: {
      DE: true,
    },
  },
  ENABLE_PRODUCTION_PERIOD: {
    enabledGlobally: true,
  },
});

function getClientConfig(): ClientConfig {
  const url = new URL(window.location.href);

  const language = url.searchParams.get(`language`) || `de`;
  const preview = url.searchParams.get(`preview`) === `true`;
  const envName =
    (url.searchParams.get(`envName`) as EnvNameV3) || (`dev` as EnvNameV3);
  const marketId =
    (url.searchParams.get(`marketId`) as MarketId) || (`de` as MarketId);
  const languageTag = getLanguageTag(language, marketId);

  const endpointDirectory: EndpointDirectoryV3 = {
    //TODO: Not needed but verify if it's needed
    rotatingVerifySecret: undefined,
    envName,
    preview,
  };
  return {
    locale: {marketId, languageTag, language},
    endpointDirectory,
  };
}
const clientConfig = getClientConfig();
const createIntegrator = () =>
  createFeatureAppIntegrator({
    App: ({endpointDirectory: {envName}, locale}) => (
      <ComponentProvider theme="light" locale={locale.languageTag}>
        <FeatureApp name="shopping-cart-app" envName={envName} />
        <FeatureApp name="payment-calculator-app" envName={envName} />
      </ComponentProvider>
    ),
    id: `shopping-cart-integrator`,
    clientConfig,
  });

const isLocal =
  process.env.NODE_ENV === `development` &&
  window.location.hostname === `localhost`;

isLocal
  ? fetchFeatureFlags({
      projectId: `website`,
      marketId: clientConfig.locale.marketId as MarketId,
      envName: clientConfig.endpointDirectory.envName,
      preview: clientConfig.endpointDirectory.preview,
    })
      .then((flags) => {
        const script = document.createElement(`script`);
        script.id = `featureFlags`;
        script.type = `application/x-www-form-urlencoded`;
        script.innerHTML = encodeURIComponent(JSON.stringify(flags));
        document.head.appendChild(script);
        createIntegrator();
      })
      .catch((e) => {
        console.error(`Error fetching feature flags`, e);
      })
  : createIntegrator();

